/**
 * dsh-rule-manager host 入口。
 *
 * 合并自 dsh-global-rules 与 dsh-rule-splitter：
 *   1) GET/POST /global-rules        —— 读写用户全局规则 $DSH_HOME/AGENTS.md；
 *   2) GET /rule-splitter/workspaces —— 列出已注册的工作区；
 *   3) GET /rule-splitter/models     —— 模型目录（供拆分 tab 选择模型）；
 *   4) GET/POST /rule-splitter/rules —— 读写某工作区内的 AGENTS.md（项目规则编辑）；
 *   5) GET /rule-splitter/rule-files —— 列出工作区全部规则文件；
 *   6) POST /rule-splitter/split     —— LLM 将粘贴的规则拆分为分层 AGENTS.md（预览）；
 *   7) POST /rule-splitter/apply     —— 确认后写盘（覆盖前自动备份）。
 *
 * 所有路由路径与旧插件保持一致，保证已装旧版本时功能零破坏。
 * 安装：装进 web profile 后重启 dsh web，打开 设置 -> 规则管理。
 */
import { readFile, writeFile, mkdir, readdir, copyFile } from 'node:fs/promises'
import { homedir } from 'node:os'
import { join, dirname, relative, sep } from 'node:path'

export const name = 'rule-manager'

export const inject = ['llm', 'agentDefaultModel', 'webServer', 'workspaceRegistry']

const MAX_BODY_BYTES = 512 * 1024
const MAX_RULES_BODY_BYTES = 256 * 1024
const SPLIT_TIMEOUT_MS = 180_000
const MAX_OUTPUT_TOKENS = 16000
const MAX_DIR_DEPTH = 3
const MAX_FILES = 12

/** Resolve the harness home: `$DSH_HOME` wins, else `~/.dsh` (matches the
 * engine's dsh-home-paths semantics — blank/whitespace DSH_HOME counts as
 * unset). Keeps the global-rules panel in sync with where the engine actually
 * loads AGENTS.md from, e.g. the desktop shell's portable <program>/data. */
function dshHomeDir() {
  const fromEnv = process.env.DSH_HOME
  if (fromEnv !== undefined && fromEnv.trim().length > 0) return fromEnv
  return join(homedir(), '.dsh')
}

function sendJson(response, status, payload) {
  response.writeHead(status, {
    'cache-control': 'no-store',
    'content-type': 'application/json; charset=utf-8',
  })
  response.end(JSON.stringify(payload))
}

/** True when the request's Origin matches its Host — required on POST. */
function sameOrigin(request) {
  const origin = request.headers.origin
  const host = request.headers.host
  if (origin === undefined || host === undefined) return false
  try {
    return new URL(origin).host === host
  } catch {
    return false
  }
}

/** Read and parse a JSON request body, capped at a given byte limit. */
async function readJsonBody(request, capBytes) {
  const chunks = []
  let size = 0
  for await (const chunk of request) {
    const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk)
    size += buffer.length
    if (size > capBytes) throw new Error('request body too large')
    chunks.push(buffer)
  }
  return JSON.parse(Buffer.concat(chunks).toString('utf8'))
}

/** Collect text deltas from an llm.stream() chunk sequence. */
async function collectText(stream, signal) {
  let text = ''
  let reasoning = ''
  let finish = null
  for await (const chunk of stream) {
    signal?.throwIfAborted()
    if (chunk.type === 'text-delta') {
      text += chunk.text
    } else if (chunk.type === 'reasoning-delta') {
      reasoning += chunk.text
    } else if (chunk.type === 'finish') {
      finish = chunk.reason
    }
  }
  return { text, reasoning, finish }
}

/** Extract the first JSON value from model output (tolerates fences/prose). */
function extractJson(text) {
  const trimmed = text.trim()
  // 1) 纯 JSON：以 { 开头，直接取到最后一个 }
  if (trimmed.startsWith('{')) {
    const end = trimmed.lastIndexOf('}')
    if (end > 0) return JSON.parse(trimmed.slice(0, end + 1))
  }
  // 2) 围栏包裹：以 ```json 或 ``` 开头且以 ``` 结尾。锚定首尾，避免
  //    把 content 字段里内嵌的 ```python 代码块误判为围栏边界。
  const fenced = trimmed.match(/^```(?:json)?\s*\n?([\s\S]*?)\n?\s*```\s*$/)
  if (fenced) {
    const inner = fenced[1].trim()
    const start = inner.indexOf('{')
    const end = inner.lastIndexOf('}')
    if (start >= 0 && end > start) return JSON.parse(inner.slice(start, end + 1))
  }
  // 3) 兜底：任意文本中首个 { 到最后一个 }
  const start = trimmed.indexOf('{')
  const end = trimmed.lastIndexOf('}')
  if (start >= 0 && end > start) return JSON.parse(trimmed.slice(start, end + 1))
  throw new Error('模型输出中没有找到 JSON 对象')
}

/** Extract JSON from text, falling back to reasoning content when text lacks it. */
function extractSplitJson(text, reasoning) {
  if (text.trim() !== '') {
    try {
      return extractJson(text)
    } catch (error) {
      if (reasoning.trim() === '') throw error
    }
  }
  return extractJson(reasoning)
}

/** Walk a workspace directory tree, returning relative directory paths. */
async function listDirectories(root, maxDepth) {
  const dirs = []
  async function walk(current, depth) {
    if (depth > maxDepth) return
    let entries
    try {
      entries = await readdir(current, { withFileTypes: true })
    } catch {
      return
    }
    for (const entry of entries) {
      if (!entry.isDirectory()) continue
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.idea') continue
      const absolute = join(current, entry.name)
      const rel = relative(root, absolute)
      if (rel.length > 0 && !rel.startsWith('..')) {
        dirs.push(rel.split(sep).join('/'))
      }
      await walk(absolute, depth + 1)
    }
  }
  await walk(root, 0)
  return dirs
}

/** Scan a workspace for every EXISTING rule file (AGENTS.md + skills, depth-bounded). */
async function listRuleFiles(root, maxDepth) {
  const files = []
  async function walk(current, depth) {
    if (depth > maxDepth) return
    let entries
    try {
      entries = await readdir(current, { withFileTypes: true })
    } catch {
      return
    }
    // 该目录自身的 AGENTS.md（存在才收录）
    const own = join(current, 'AGENTS.md')
    try {
      await readFile(own, 'utf8')
      const rel = relative(root, own)
      const relSlash = rel.split(sep).join('/')
      files.push({ dir: relSlash === 'AGENTS.md' ? '' : relSlash.replace(/\/AGENTS\.md$/, ''), displayPath: relSlash, absolutePath: own, relPath: relSlash })
    } catch (error) {
      if (error && error.code !== 'ENOENT') throw error
    }
    // 该目录若为 .dsh/skills 或 .agents/skills，扫描其子目录的 SKILL.md
    const base = current.split(sep).slice(-2).join('/')
    if (base === '.dsh/skills' || base === '.agents/skills') {
      for (const entry of entries) {
        if (!entry.isDirectory()) continue
        const skillFile = join(current, entry.name, 'SKILL.md')
        try {
          await readFile(skillFile, 'utf8')
          const rel = relative(root, skillFile).split(sep).join('/')
          files.push({ dir: rel.replace(/\/SKILL\.md$/, ''), displayPath: rel, absolutePath: skillFile, relPath: rel })
        } catch (error) {
          if (error && error.code !== 'ENOENT') throw error
        }
      }
    }
    for (const entry of entries) {
      if (!entry.isDirectory()) continue
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.idea') continue
      await walk(join(current, entry.name), depth + 1)
    }
  }
  await walk(root, 0)
  // 确保根目录 AGENTS.md 排在第一位（即使不存在也占位，编辑可新建）
  const rootEntry = files.find((f) => f.dir === '')
  if (rootEntry === undefined) {
    files.unshift({ dir: '', displayPath: 'AGENTS.md', absolutePath: join(root, 'AGENTS.md'), relPath: 'AGENTS.md' })
  }
  return files
}

/**
 * Resolve a workspace-relative rule file path to a safe absolute path.
 * `relativePath` may be a directory ('' or 'a/b' → appends AGENTS.md) or a
 * full relative file path ('AGENTS.md', '.dsh/skills/x/SKILL.md').
 */
function resolveRuleFile(workspacePath, relativePath) {
  const rel = typeof relativePath === 'string' ? relativePath.replace(/\\/g, '/').replace(/^\.\//, '') : ''
  const segments = rel.split('/').filter((segment) => segment !== '' && segment !== '.')
  if (segments.some((segment) => segment === '..')) {
    throw new Error(`规则文件路径越界: "${relativePath}"`)
  }
  if (segments.length === 0) return join(workspacePath, 'AGENTS.md')
  const last = segments[segments.length - 1]
  // 末尾是 .md 文件 → 当作完整路径；否则当作目录 → 补 AGENTS.md
  const full = last.endsWith('.md') ? segments : [...segments, 'AGENTS.md']
  return join(workspacePath, ...full)
}

/** Guard a model-proposed relative dir against escaping the workspace. */
function sanitizeRelativeDir(candidate, root) {
  if (typeof candidate !== 'string' || candidate.length === 0) return ''
  const normalized = candidate.replace(/\\/g, '/').replace(/^\.\//, '')
  const segments = normalized.split('/').filter((segment) => segment !== '' && segment !== '.')
  if (segments.some((segment) => segment === '..')) {
    throw new Error(`模型提议的目录越界: "${candidate}"`)
  }
  if (segments.length > MAX_DIR_DEPTH) {
    throw new Error(`模型提议的目录过深: "${candidate}"`)
  }
  return segments.join('/')
}

/**
 * Guard a model-proposed relative file path (may include a file name, e.g.
 * ".dsh/skills/import-order/SKILL.md" or "AGENTS.md") against escaping the
 * workspace. Only .md files are allowed as explicit names.
 */
function sanitizeRelativePath(candidate) {
  if (typeof candidate !== 'string' || candidate.length === 0) return 'AGENTS.md'
  const normalized = candidate.replace(/\\/g, '/').replace(/^\.\//, '')
  const segments = normalized.split('/').filter((segment) => segment !== '' && segment !== '.')
  if (segments.some((segment) => segment === '..')) {
    throw new Error(`模型提议的路径越界: "${candidate}"`)
  }
  if (segments.length > MAX_DIR_DEPTH + 2) {
    throw new Error(`模型提议的路径过深: "${candidate}"`)
  }
  const last = segments[segments.length - 1]
  if (!last.endsWith('.md')) {
    throw new Error(`模型提议的文件名必须是 .md: "${candidate}"`)
  }
  return segments.join('/')
}

/** Skill name must match DSH's `^[a-z0-9]+(?:-[a-z0-9]+)*$`. */
function sanitizeSkillName(name) {
  if (typeof name !== 'string' || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(name)) {
    throw new Error(`skill 名称不合法（需小写字母/数字/连字符）: "${String(name)}"`)
  }
  return name
}

/** Assemble a SKILL.md body with YAML frontmatter from model-provided fields. */
function buildSkillContent(item) {
  const name = sanitizeSkillName(item.name)
  const description = typeof item.description === 'string' && item.description.trim() !== '' ? item.description.trim() : name
  const whenToUse = typeof item.whenToUse === 'string' && item.whenToUse.trim() !== '' ? item.whenToUse.trim() : null
  const lines = ['---', `name: ${name}`, `description: >`, ...description.split('\n').map((l) => `  ${l}`)]
  if (whenToUse !== null) lines.push('whenToUse: >', ...whenToUse.split('\n').map((l) => `  ${l}`))
  lines.push('---', '', item.content)
  return lines.join('\n')
}

/** Build the split plan from a model JSON payload. */
function normalizePlan(payload, workspacePath) {
  const rawFiles = Array.isArray(payload) ? payload : Array.isArray(payload?.files) ? payload.files : null
  if (rawFiles === null) throw new Error('模型输出结构不符合预期（缺少 files 数组）')
  if (rawFiles.length > MAX_FILES) throw new Error(`模型输出文件数 ${rawFiles.length} 超过上限 ${MAX_FILES}`)
  return rawFiles.map((item, index) => {
    if (item === null || typeof item !== 'object') throw new Error(`files[${index}] 不是对象`)
    // path: 完整相对路径（可含文件名，如 ".dsh/skills/import/SKILL.md" 或 "AGENTS.md"）。
    // dir: 兼容旧格式，目录 + AGENTS.md。
    const relPath = sanitizeRelativePath(item.path ?? (item.dir === undefined ? 'AGENTS.md' : (item.dir === '' ? 'AGENTS.md' : item.dir + '/AGENTS.md')))
    const rawContent = typeof item.content === 'string' ? item.content : ''
    if (rawContent.length === 0) throw new Error(`files[${index}] 内容为空`)
    // 只有路径以 /SKILL.md 结尾才是 skill（带 frontmatter）；根 AGENTS.md 及
    // 其他普通 md 一律不加 frontmatter，即使模型误带了 name 字段。
    const isSkill = relPath.endsWith('/SKILL.md') || relPath === 'SKILL.md'
    const content = isSkill
      ? buildSkillContent({ name: item.name ?? relPath.split('/').filter((s) => s !== 'SKILL.md' && s !== '.dsh' && s !== 'skills').pop(), description: item.description, whenToUse: item.whenToUse, content: rawContent })
      : rawContent
    return { relPath, content, isSkill }
  })
}

/** Write one split file, backing up an existing target first. */
async function writeWithBackup(absolutePath, content) {
  let backupPath = null
  try {
    await readFile(absolutePath, 'utf8')
    backupPath = `${absolutePath}.bak-${Date.now()}`
    await copyFile(absolutePath, backupPath)
  } catch (error) {
    if (error && error.code !== 'ENOENT') throw error
  }
  await mkdir(dirname(absolutePath), { recursive: true })
  await writeFile(absolutePath, content, 'utf8')
  return backupPath
}

/** Parse the `workspace` query parameter from the request URL. */
function workspaceParam(request) {
  try {
    const url = new URL(request.url, 'http://localhost')
    return url.searchParams.get('workspace')
  } catch {
    return null
  }
}

export function apply(ctx) {
  ctx.inject(['llm', 'agentDefaultModel', 'webServer', 'workspaceRegistry'], (host) => {
    // ── 1) 全局规则：读写 $DSH_HOME/AGENTS.md（原 dsh-global-rules）────────
    host.effect(() => host.webServer.register({
      kind: 'exact',
      path: '/global-rules',
      handler: async (request, response) => {
        const file = join(dshHomeDir(), 'AGENTS.md')
        if (request.method === 'GET') {
          try {
            const content = await readFile(file, 'utf8')
            sendJson(response, 200, { exists: true, content, home: dshHomeDir() })
          } catch (error) {
            if (error && error.code === 'ENOENT') {
              sendJson(response, 200, { exists: false, content: '', home: dshHomeDir() })
            } else {
              sendJson(response, 500, { error: String(error && error.message || error) })
            }
          }
          return
        }
        if (request.method === 'POST') {
          if (!sameOrigin(request)) {
            response.writeHead(403)
            response.end()
            return
          }
          try {
            const body = await readJsonBody(request, MAX_RULES_BODY_BYTES)
            const content = typeof body === 'object' && body !== null ? body.content : undefined
            if (typeof content !== 'string') {
              sendJson(response, 400, { error: 'content must be a string' })
              return
            }
            await writeFile(file, content, 'utf8')
            sendJson(response, 200, { ok: true })
          } catch (error) {
            sendJson(response, 500, { error: String(error && error.message || error) })
          }
          return
        }
        response.writeHead(405, { allow: 'GET, POST' })
        response.end()
      },
    }), 'dsh-rule-manager: global-rules route')

    // ── 2) 工作区列表（原 dsh-rule-splitter）────────────────────────────────
    host.effect(() => host.webServer.register({
      kind: 'exact',
      path: '/rule-splitter/workspaces',
      handler: async (request, response) => {
        if (request.method !== 'GET') {
          response.writeHead(405, { allow: 'GET' })
          response.end()
          return
        }
        try {
          const workspaces = host.workspaceRegistry.list().map((workspace) => ({
            id: workspace.id,
            title: workspace.title,
            path: workspace.path,
          }))
          sendJson(response, 200, { workspaces })
        } catch (error) {
          sendJson(response, 500, { error: String(error && error.message || error) })
        }
      },
    }), 'dsh-rule-manager: workspace list route')

    // ── 3) 模型目录：列出注册的 provider 与模型 ──────────────────────────────
    host.effect(() => host.webServer.register({
      kind: 'exact',
      path: '/rule-splitter/models',
      handler: async (request, response) => {
        if (request.method !== 'GET') {
          response.writeHead(405, { allow: 'GET' })
          response.end()
          return
        }
        try {
          const providers = host.llm.listProviders()
          const catalog = []
          for (const provider of providers) {
            const models = await host.llm.listModels(provider.id)
            catalog.push({
              id: provider.id,
              name: provider.name,
              models: models.map((model) => ({ id: model.id, name: model.name })),
            })
          }
          const selection = host.agentDefaultModel.currentSelection()
          sendJson(response, 200, {
            providers: catalog,
            default: { provider: selection.provider, model: selection.model },
          })
        } catch (error) {
          sendJson(response, 500, { error: String(error && error.message || error) })
        }
      },
    }), 'dsh-rule-manager: model catalog route')

    // ── 4) 项目规则编辑：GET 读规则文件，POST 写（同源校验）──────────────────
    host.effect(() => host.webServer.register({
      kind: 'exact',
      path: '/rule-splitter/rules',
      handler: async (request, response) => {
        const workspaceId = workspaceParam(request)
        if (workspaceId === null || workspaceId === '') {
          sendJson(response, 400, { error: 'workspace query parameter is required' })
          return
        }
        const workspace = host.workspaceRegistry.get(workspaceId)
        if (workspace === undefined) {
          sendJson(response, 404, { error: 'unknown workspace' })
          return
        }
        let file
        try {
          const url = new URL(request.url, 'http://localhost')
          file = resolveRuleFile(workspace.path, url.searchParams.get('file') ?? '')
        } catch (error) {
          sendJson(response, 400, { error: String(error && error.message || error) })
          return
        }
        const relDisplay = relative(workspace.path, file).split(sep).join('/')

        if (request.method === 'GET') {
          try {
            const content = await readFile(file, 'utf8')
            sendJson(response, 200, { exists: true, content, path: workspace.path, file: relDisplay })
          } catch (error) {
            if (error && error.code === 'ENOENT') {
              sendJson(response, 200, { exists: false, content: '', path: workspace.path, file: relDisplay })
            } else {
              sendJson(response, 500, { error: String(error && error.message || error) })
            }
          }
          return
        }
        if (request.method === 'POST') {
          if (!sameOrigin(request)) {
            response.writeHead(403)
            response.end()
            return
          }
          try {
            const body = await readJsonBody(request, MAX_RULES_BODY_BYTES)
            const content = typeof body === 'object' && body !== null ? body.content : undefined
            if (typeof content !== 'string') {
              sendJson(response, 400, { error: 'content must be a string' })
              return
            }
            await writeFile(file, content, 'utf8')
            sendJson(response, 200, { ok: true })
          } catch (error) {
            sendJson(response, 500, { error: String(error && error.message || error) })
          }
          return
        }
        response.writeHead(405, { allow: 'GET, POST' })
        response.end()
      },
    }), 'dsh-rule-manager: rules route')

    // ── 5) 规则文件列表：工作区所有 AGENTS.md + skills ──────────────────────
    host.effect(() => host.webServer.register({
      kind: 'exact',
      path: '/rule-splitter/rule-files',
      handler: async (request, response) => {
        if (request.method !== 'GET') {
          response.writeHead(405, { allow: 'GET' })
          response.end()
          return
        }
        const workspaceId = workspaceParam(request)
        if (workspaceId === null || workspaceId === '') {
          sendJson(response, 400, { error: 'workspace query parameter is required' })
          return
        }
        const workspace = host.workspaceRegistry.get(workspaceId)
        if (workspace === undefined) {
          sendJson(response, 404, { error: 'unknown workspace' })
          return
        }
        try {
          const files = await listRuleFiles(workspace.path, MAX_DIR_DEPTH)
          const withExists = []
          for (const f of files) {
            let exists = false
            try {
              await readFile(f.absolutePath, 'utf8')
              exists = true
            } catch (error) {
              if (error && error.code !== 'ENOENT') exists = true
            }
            withExists.push({ dir: f.dir, displayPath: f.displayPath, relPath: f.relPath, exists })
          }
          sendJson(response, 200, { files: withExists })
        } catch (error) {
          sendJson(response, 500, { error: String(error && error.message || error) })
        }
      },
    }), 'dsh-rule-manager: rule-files list route')

    // ── 6) 拆分预览：LLM 生成分层计划，不写盘 ────────────────────────────────
    host.effect(() => host.webServer.register({
      kind: 'exact',
      path: '/rule-splitter/split',
      handler: async (request, response) => {
        if (request.method !== 'POST') {
          response.writeHead(405, { allow: 'POST' })
          response.end()
          return
        }
        if (!sameOrigin(request)) {
          response.writeHead(403)
          response.end()
          return
        }
        let body
        try {
          body = await readJsonBody(request, MAX_BODY_BYTES)
        } catch (error) {
          sendJson(response, 400, { error: '请求体解析失败: ' + String(error && error.message || error) })
          return
        }
        const workspaceId = typeof body.workspaceId === 'string' ? body.workspaceId : ''
        const rules = typeof body.rules === 'string' ? body.rules : ''
        const mode = body.mode === 'merge' ? 'merge' : 'overwrite'
        if (workspaceId === '' || rules.trim() === '') {
          sendJson(response, 400, { error: 'workspaceId 与 rules 均为必填' })
          return
        }
        const workspace = host.workspaceRegistry.get(workspaceId)
        if (workspace === undefined) {
          sendJson(response, 404, { error: 'unknown workspace' })
          return
        }
        const workspacePath = workspace.path

        let controller
        try {
          controller = new AbortController()
          const timer = setTimeout(() => controller.abort(), SPLIT_TIMEOUT_MS)
          const defaultSelection = host.agentDefaultModel.currentSelection()
          // Optional per-request model override; falls back to the deployment default.
          const requestedProvider = typeof body.provider === 'string' && body.provider !== '' ? body.provider : defaultSelection.provider
          const requestedModel = typeof body.model === 'string' && body.model !== '' ? body.model : defaultSelection.model
          const selection = { provider: requestedProvider, model: requestedModel }
          const dirs = await listDirectories(workspacePath, MAX_DIR_DEPTH)
          // merge 模式：把工作区已有的 AGENTS.md（根 + 子目录）读入，让模型
          // 在拆分阶段就输出融合了旧规则的内容（预览即合并结果）。
          let existingRules = null
          if (mode === 'merge') {
            existingRules = []
            const files = await listRuleFiles(workspacePath, MAX_DIR_DEPTH)
            for (const f of files) {
              try {
                const content = await readFile(f.absolutePath, 'utf8')
                if (content.trim() !== '') {
                  existingRules.push({ displayPath: f.displayPath, content })
                }
              } catch (error) {
                if (error && error.code !== 'ENOENT') throw error
              }
            }
          }
          const prompt = buildSplitPrompt(rules, dirs, workspacePath, mode, existingRules)
          const stream = host.llm.stream({
            provider: selection.provider,
            model: selection.model,
            messages: [createUserMessage(prompt)],
            system: SPLIT_SYSTEM_PROMPT,
            maxTokens: MAX_OUTPUT_TOKENS,
            purpose: 'rule-manager',
            reasoningEffort: 'off',
            signal: controller.signal,
          })
          const { text, reasoning, finish } = await collectText(stream, controller.signal)
          clearTimeout(timer)
          if (finish && (finish.kind === 'error' || finish.kind === 'aborted')) {
            throw new Error(`模型调用失败: ${finish.failure?.message ?? String(finish.kind)}`)
          }
          if (finish && finish.kind === 'max-tokens') {
            throw new Error('模型输出超出 token 上限，请减少规则内容后重试')
          }
          const plan = normalizePlan(extractSplitJson(text, reasoning), workspacePath)
          // 预览阶段：只计算目标路径与是否会覆盖已有文件，不写盘。
          const results = []
          for (const item of plan) {
            const absolutePath = join(workspacePath, ...item.relPath.split('/'))
            let exists = false
            try {
              await readFile(absolutePath, 'utf8')
              exists = true
            } catch (error) {
              if (error && error.code !== 'ENOENT') throw error
            }
            results.push({
              path: item.relPath,
              dir: item.relPath === 'AGENTS.md' ? '.' : item.relPath.replace(/\/[^/]+$/, ''),
              absolutePath,
              overwrites: exists,
              content: item.content,
            })
          }
          sendJson(response, 200, {
            ok: true,
            mode,
            model: { provider: selection.provider, model: selection.model },
            files: results,
          })
        } catch (error) {
          if (controller && controller.signal.aborted) {
            sendJson(response, 500, { error: '模型调用超时（180 秒），请重试或减少规则内容' })
          } else {
            sendJson(response, 500, { error: String(error && error.message || error) })
          }
        }
      },
    }), 'dsh-rule-manager: split route')

    // ── 7) 确认写盘：客户端确认预览后才写入，覆盖前备份 ──────────────────────
    host.effect(() => host.webServer.register({
      kind: 'exact',
      path: '/rule-splitter/apply',
      handler: async (request, response) => {
        if (request.method !== 'POST') {
          response.writeHead(405, { allow: 'POST' })
          response.end()
          return
        }
        if (!sameOrigin(request)) {
          response.writeHead(403)
          response.end()
          return
        }
        let body
        try {
          body = await readJsonBody(request, MAX_BODY_BYTES)
        } catch (error) {
          sendJson(response, 400, { error: '请求体解析失败: ' + String(error && error.message || error) })
          return
        }
        const workspaceId = typeof body.workspaceId === 'string' ? body.workspaceId : ''
        const rawFiles = Array.isArray(body.files) ? body.files : null
        const mode = body.mode === 'merge' ? 'merge' : 'overwrite'
        if (workspaceId === '' || rawFiles === null || rawFiles.length === 0) {
          sendJson(response, 400, { error: 'workspaceId 与 files 均为必填' })
          return
        }
        const workspace = host.workspaceRegistry.get(workspaceId)
        if (workspace === undefined) {
          sendJson(response, 404, { error: 'unknown workspace' })
          return
        }
        const workspacePath = workspace.path
        try {
          const plan = rawFiles.map((item, index) => {
            if (item === null || typeof item !== 'object') throw new Error(`files[${index}] 不是对象`)
            const relPath = sanitizeRelativePath(item.path ?? (item.dir === undefined ? 'AGENTS.md' : (item.dir === '' ? 'AGENTS.md' : item.dir + '/AGENTS.md')))
            const content = typeof item.content === 'string' ? item.content : ''
            if (content.length === 0) throw new Error(`files[${index}] 内容为空`)
            return { relPath, content }
          })
          // merge 的合并已在 /split 阶段完成，这里统一执行：备份 → 写盘。
          const results = []
          for (const item of plan) {
            const absolutePath = join(workspacePath, ...item.relPath.split('/'))
            const backupPath = await writeWithBackup(absolutePath, item.content)
            results.push({
              path: item.relPath,
              dir: item.relPath === 'AGENTS.md' ? '.' : item.relPath.replace(/\/[^/]+$/, ''),
              absolutePath,
              backupPath,
            })
          }
          sendJson(response, 200, { ok: true, mode, files: results })
        } catch (error) {
          sendJson(response, 500, { error: String(error && error.message || error) })
        }
      },
    }), 'dsh-rule-manager: apply route')
  })
}

/** Frame the user prompt with the rules blob and the existing directory tree. */
function buildSplitPrompt(rules, dirs, workspacePath, mode, existingRules) {
  const parts = [
    '用户提供的项目规则原文：',
    '```',
    rules,
    '```',
    '',
    '工作区路径：' + workspacePath,
  ]
  if (mode === 'merge' && existingRules !== null && existingRules.length > 0) {
    parts.push(
      '',
      '工作区【已有的规则文件】及其内容（merge 模式：必须保留其中仍然有效的规则，把它们与新规则融合进输出，同样按主题拆分）：',
    )
    for (const file of existingRules) {
      parts.push(
        '',
        `--- ${file.displayPath} ---`,
        '```',
        file.content,
        '```',
      )
    }
  }
  return parts.join('\n')
}

/** Build a user message in the same shape the harness LLM service expects. */
function createUserMessage(text) {
  return deepFreeze({
    id: crypto.randomUUID(),
    role: 'user',
    content: [{ type: 'text', text }],
    source: { kind: 'plugin', plugin: 'dsh-rule-manager' },
  })
}

/** Recursively freeze a plain JSON-compatible value (adapter boundary contract). */
function deepFreeze(value) {
  if (value === null || typeof value !== 'object' || Object.isFrozen(value)) return value
  for (const key of Object.keys(value)) deepFreeze(value[key])
  return Object.freeze(value)
}

const SPLIT_SYSTEM_PROMPT = [
  '你是 DSH 项目的规则拆分器。用户会把一整份项目规则贴给你，你的任务是把它们拆成【精简总纲 + 按需加载的 skill 技能】。',
  '',
  'DSH 的加载机制：',
  '- AGENTS.md 会自动加载，所以必须精简，只留核心规则 + skill 索引；',
  '- .dsh/skills/<name>/SKILL.md 是「技能」，模型平时只看到简短摘要（description/whenToUse），只有任务匹配时才加载全文——这才是"按需读取"的正确载体。',
  '',
  '输出要求（严格遵守）：',
  '1. 只输出一个 JSON 对象，不要输出任何解释、代码块围栏外的文字或 Markdown。',
  '2. JSON 结构：{"files": [{"path": "相对路径", "content": "...", "name": "...", "description": "...", "whenToUse": "..."}]}',
  '3. 根目录总纲：path 为 "AGENTS.md"，content 只写【精简核心规则 + skill 索引清单】，不要带 name/description/whenToUse 字段。',
  '   - 核心规则控制在几句话（语言、命名、安全底线等最高频约定）；',
  '   - 索引清单格式："涉及 <场景> 时，调用 skill：<skill 名>"，让模型按需加载。',
  '4. 详细规则拆成 skill：每个主题一个 skill，path 为 ".dsh/skills/<英文名>/SKILL.md"。',
  '   - "name" 用小写英文 + 连字符（如 import-order、dependencies、fast-web-core、team-id、export）；',
  '   - "description" 一句话概括该规则内容；',
  '   - "whenToUse" 写清触发场景（"写 Python import 时"、"改 requirements.txt 时"等），越具体越好；',
  '   - "content" 是该主题的完整规则正文（Markdown，不含 frontmatter，frontmatter 由代码自动生成）。',
  '5. 拆分策略（先判断是否拆分，再决定拆几份）：',
  '   - 【不拆】规则很少：总字数 ≤ 800 字，或只包含 ≤ 2 个主题。此时只输出一个根目录文件（path 为 "AGENTS.md"），content 直接写完整规则正文，不拆任何 skill。',
  '   - 【拆】规则较多：总字数 > 800 字 且 包含 ≥ 3 个明显不同的主题。此时根目录 AGENTS.md 写精简索引，详细规则按主题拆成多个 skill。',
  '   - skill 总数不要超过 12 个；宁可少拆，不要为了拆而拆。',
  '6. skill 正文不要重复总纲内容，只写该主题专属的规则。',
].join('\n')
